    { date: "2026-06-16", busy: [{ start: "11:00", end: "12:00" }] },
    { date: "2026-06-17", busy: [{ start: "15:30", end: "16:30" }] },
    { date: "2026-06-18", busy: [] },
    { date: "2026-06-19", busy: [] }
  ]}
]

to_mins = fun(t) {
  parts = text.split(t, ":")
  h = number.parse(parts[0])
  m = number.parse(parts[1])
  return h * 60 + m
}

# Build map date -> list of busy intervals (as [start_min, end_min]) merged across all users
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]
day_busy = fold acc = {} for d in dates {
  all_busy = fold bacc = [] for u in avails {
    day = fold found = null for day in u.days {
      return day if day.date == d else found
    }
    intervals = for iv in day.busy {
      return { start: to_mins(iv.start), end: to_mins(iv.end) }
    }
    return bacc + intervals
  }
  return acc + { [d]: all_busy }
}

# Possible start minutes: 9:00=540 to 16:00=960 step 30
starts = list.range(540, 961, 30)

# Check each day and start
# A slot [s, s+60] conflicts if any busy has busy.start < s+60 and busy.end > s
candidates = fold found = null for d in dates {
  skip if found != null
  day_starts = fold f2 = null for s in starts {
    skip if f2 != null
    end_m = s + 60
    # still within working hours: end <= 17:00=1020
    skip if end_m > 1020
    conflicts = fold c = false for iv in day_busy[d] {
      hit = iv.start < end_m and iv.end > s
      return true if hit else c
    }
    return { date: d, start: s, end: end_m } if not conflicts else null
  }
  return day_starts
}

# Format result
assert(candidates != null, "no slot found")
sh = number.floor(candidates.start / 60)
sm = candidates.start - sh * 60
eh = number.floor(candidates.end / 60)
em = candidates.end - eh * 60
pad = fun(n) { return text.slice("0" + json.encode(n), -2) }
start_iso = candidates.date + "T" + pad(sh) + ":" + pad(sm) + ":00Z"
end_iso = candidates.date + "T" + pad(eh) + ":" + pad(em) + ":00Z"
return { start: start_iso, end: end_iso, debug: candidates }

