dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

# Convert HH:MM to minutes for all busy intervals, grouped by date
day_busy = fold acc = {} for d in dates {
  all_busy = fold bacc = [] for u in avails {
    day_entry = fold found = null for day in u.days {
      return day if day.date == d else found
    }
    intervals = for iv in day_entry.busy {
      sp = text.split(iv.start, ":")
      ep = text.split(iv.end, ":")
      sm = number.parse(sp[0]) * 60 + number.parse(sp[1])
      em = number.parse(ep[0]) * 60 + number.parse(ep[1])
      return { start: sm, end: em }
    }
    return bacc + intervals
  }
  return acc + { [d]: all_busy }
}

